		// Then E[p^e] = sum_{j=0}^{exp} dp[k][j] * p^j
		// This is O(k * exp^2), which is too slow for exp up to 50 (since n <= 10^15, max exp is ~50 for p=2)
		// But k is up to 10^4, so 10^4 * 50^2 = 25 million, which should be fine.
		// Let's implement this.

		// Precompute p^0, p^1, ..., p^exp
		pows := make([]int64, exp+1)
		pows[0] = 1
		for i := 1; i <= exp; i++ {
