		// dp[i+1] = average of dp[i] over all divisors, which means averaging over all exponents from 0 to current exponent
		// But the current exponent changes randomly, so we need to track the distribution

		// Actually, let's think of it differently.
		// Let E[i][x] = expected value of p^x after i steps, given that we start at exponent x
		// E[0][x] = p^x
		// E[i+1][x] = (1/(x+1)) * sum_{j=0}^{x} E[i][j]
		// We want E[k][e]

		// But this is O(k * e^2) which is too slow for large e.
		// However, e is at most log_2(n) which is about 50 for n=1e15.

		// Let's compute E[k][e] using dynamic programming
		// E[i][x] for x from 0 to e

		// Initialize
		maxE := e
		dp := make([]int64, maxE+1)
		for x := int64(0); x <= maxE; x++ {
			dp[x] = modPow(p, x)
		}

		for step := int64(0); step < k; step++ {
			newDp := make([]int64, maxE+1)
			for x := int64(0); x <= maxE; x++ {
				// E[step+1][x] = (1/(x+1)) * sum_{j=0}^{x} E[step][j]
				sum := int64(0)
				for j := int64(0); j <= x; j++ {
					sum = (sum + dp[j]) % MOD
				}
				newDp[x] = sum * modInv(x+1) % MOD
			}
			dp = newDp
		}

		result = result * dp[e] % MOD
	}

	fmt.Println(result)
}
