				// fCurr[i] = (fCurr[i-1] * i + fPrev[i]) / (i+1)
				fCurr[i] = (fCurr[i-1]*int64(i) + fPrev[i]) % MOD
				fCurr[i] = fCurr[i] * modinv(int64(i+1)) % MOD
			}
			fPrev = fCurr
		}

