		factors[n]++
	}
	return factors
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, k int64
	fmt.Fscan(in, &n, &k)

	factors := factorize(n)

	result := int64(1)

	for p, e := range factors {
		// dp[i] = expected value of p^j after i steps, starting from exponent e
		// We need to compute dp[k]
		// dp[0][j] = p^j for j from 0 to e
		// dp[i][j] = (sum_{d | p^j} dp[i-1][d]) / (number of divisors of p^j)
		// number of divisors of p^j is j+1
		// divisors of p^j are p^0, p^1, ..., p^j

		// Initialize dp
		dp := make([]int64, e+1)
		for j := 0; j <= e; j++ {
			dp[j] = pow(p, int64(j), MOD)
		}

