	a %= MOD
	for b > 0 {
		if b&1 == 1 {
			res = res * a % MOD
		}
		a = a * a % MOD
		b >>= 1
	}
	return res
}

func factorize(n int64) map[int64]int {
	factors := make(map[int64]int)
	for i := int64(2); i*i <= n; i++ {
		for n%i == 0 {
			factors[i]++
			n /= i
		}
	}
	if n > 1 {
		factors[n]++
	}
	return factors
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, k int64
	fmt.Fscan(in, &n, &k)

	factors := factorize(n)

	result := int64(1)
	for p, e := range factors {
		// dp[i] = expected value of p^a after i steps
		// dp[0] = p^e
		// dp[i] = (sum_{a=0}^{current exponent} dp[i-1][a]) / (current exponent + 1)
		// But since we're working with exponents, we can model it as:
		// dp[i] = sum_{a=0}^{e} dp[i-1][a] / (e+1)
		// However, the current exponent changes each step.
		// Let's think differently:
		// Let f(t, a) be the expected value of p^a after t steps starting from exponent a.
		// f(0, a) = p^a
		// f(t, a) = (1/(a+1)) * sum_{b=0}^{a} f(t-1, b)
		// We need f(k, e)
		// This is a linear recurrence. We can compute it using dynamic programming.
		// But since k can be up to 10^4 and e can be up to log2(10^15) ~ 50, this is feasible.

		// dp[t][a] = expected value of p^a after t steps
		// dp[0][a] = p^a
		// dp[t][a] = (1/(a+1)) * sum_{b=0}^{a} dp[t-1][b]
		// We need dp[k][e]

		// To avoid recomputation, we can use prefix sums.
		// Let prefix[t][a] = sum_{b=0}^{a} dp[t][b]
		// Then dp[t][a] = prefix[t-1][a] / (a+1)
		// And prefix[t][a] = prefix[t][a-1] + dp[t][a]

		// Initialize dp[0][a] = p^a for a from 0 to e
		maxExp := e
		dp := make([]int64, maxExp+1)
		prefix := make([]int64, maxExp+1)

		// dp[0][a] = p^a
		pa := int64(1)
		for a := 0; a <= maxExp; a++ {
			dp[a] = pa
			if a == 0 {
				prefix[a] = pa
			} else {
				prefix[a] = (prefix[a-1] + pa) % MOD
			}
			pa = pa * p % MOD
		}

		// For each step from 1 to k
		for t := int64(1); t <= k; t++ {
			newDp := make([]int64, maxExp+1)
			newPrefix := make([]int64, maxExp+1)
			for a := 0; a <= maxExp; a++ {
				// dp[t][a] = prefix[t-1][a] / (a+1)
				newDp[a] = prefix[a] * modinv(int64(a+1)) % MOD
				if a == 0 {
					newPrefix[a] = newDp[a]
				} else {
					newPrefix[a] = (newPrefix[a-1] + newDp[a]) % MOD
				}
			}
			dp = newDp
			prefix = newPrefix
		}

		result = result * dp[maxExp] % MOD
	}

	fmt.Println(result)
}
